use anyhow::Result;use clap::{Parser,Subcommand};use destiny_protocol_analyzer::{open_database,ingest,CapturePacket,hex_view};use rusqlite::params;use std::{fs::File,io::{BufRead,BufReader},path::PathBuf};
#[derive(Parser)]struct A{#[arg(short,long,default_value="protocol.db")]database:PathBuf,#[command(subcommand)]command:C}
#[derive(Subcommand)]enum C{Ingest{capture:PathBuf},Timeline{session:String},Hex{message:i64}}
fn main()->Result<()>{let a=A::parse();let c=open_database(a.database)?;match a.command{C::Ingest{capture}=>{for line in BufReader::new(File::open(capture)?).lines(){let p:CapturePacket=serde_json::from_str(&line?)?;ingest(&c,&p)?;}},C::Timeline{session}=>{let mut s=c.prepare("select timestamp,direction,opcode,payload_size,confidence from messages where session_id=? order by timestamp")?;for r in s.query_map([session],|r|Ok((r.get::<_,i64>(0)?,r.get::<_,String>(1)?,r.get::<_,Option<u16>>(2)?,r.get::<_,i64>(3)?,r.get::<_,String>(4)?)))?{println!("{:?}",r?);}},C::Hex{message}=>{let b:Vec<u8>=c.query_row("select payload from packet_samples where message_id=?",params![message],|r|r.get(0))?;println!("{}",hex_view(&b));}}Ok(())}
